380	func TestRestoreProcessesDueAtRestoreTime(t *testing.T) {
381		w, c := backupSetup(t)
382		t0 := c.t
383		// 导出时刻 t0：pending-due（截止 t0+5m）与 resv-due（截止 t0+1m）均未到期。
384		data, err := w.Export()
385		if err != nil {
386			t.Fatal(err)
387		}
388		srcBal, _ := w.Balance("payer")
389	
390		// 恢复时刻 t0+30m：待审批已过期；预留已超时全额退回，释放时间仍是 t0+1m。
391		w2, err := restoreAt(data, t0.Add(30*time.Minute))
392		if err != nil {
393			t.Fatalf("restore: %v", err)
394		}
395	
396		pd, _ := w2.Request("u1", "pending-due")
397		if pd.State != RequestExpired {
398			t.Fatalf("pending-due state = %v, want expired", pd.State)
399		}
400		if pd.DecidedAt.IsZero() {
401			t.Fatal("expired request must record decided_at")
402		}
403		rd, _ := w2.Request("u1", "resv-due")
404		if rd.State != RequestReservationExpired {
405			t.Fatalf("resv-due state = %v, want reservation expired", rd.State)
406		}
407		if want := t0.Add(time.Minute); !rd.ReserveExpiredAt.Equal(want) {
408			t.Fatalf("release time = %v, want original deadline %v (not restore time)", rd.ReserveExpiredAt, want)
409		}
410		// 退回的 5 立即可用；预留余额相应下降。
411		gotBal, _ := w2.Balance("payer")
412		if gotBal.Available != srcBal.Available+5 || gotBal.Reserved != srcBal.Reserved-5 {
413			t.Fatalf("balance after restore = %+v, want available %d reserved %d", gotBal, srcBal.Available+5, srcBal.Reserved-5)
414		}
415		// 账本：在原账本之后追加 预留超时退款 + 超时记录 + 待审批过期记录。
416		var kinds []LedgerKind
417		for _, e := range w2.Ledger() {
418			switch {
419			case e.Kind == LedgerRefund && e.RequestID == "resv-due":
420				kinds = append(kinds, LedgerRefund)
421				if e.Amount != 5 || !e.At.Equal(t0.Add(time.Minute)) {
422					t.Fatalf("resv-due refund entry = %+v", e)
423				}
424				if e.AccountID != "payer" {
425					t.Fatalf("refund account = %q, want payer", e.AccountID)
426				}
427			case e.Kind == LedgerReservationExpiration && e.RequestID == "resv-due":
428				kinds = append(kinds, LedgerReservationExpiration)
429				if !e.At.Equal(t0.Add(time.Minute)) {
430					t.Fatalf("timeout entry at %v, want deadline", e.At)
431				}
432			case e.Kind == LedgerExpiration && e.RequestID == "pending-due":
433				kinds = append(kinds, LedgerExpiration)
434			}
435		}
436		if len(kinds) != 3 {
437			t.Fatalf("expected 3 new entries, got %v", kinds)
438		}
439	
440		// 未到期（相对 t0+30m）的请求继续等待或预留。
441		if d, _ := w2.Request("u1", "direct"); d.State != RequestReserved {
442			t.Fatalf("direct state = %v, want still reserved", d.State)
443		}
444		if a, _ := w2.Request("u2", "approved"); a.State != RequestReserved {
445			t.Fatalf("approved state = %v, want still reserved", a.State)
446		}
447		// 既有终态不改写。
448		re, _ := w2.Request("u1", "resv-expired")
449		if !re.ReserveExpiredAt.Equal(t0.Add(time.Minute)) {
450			t.Fatalf("pre-existing timeout release time rewritten: %v", re.ReserveExpiredAt)
451		}
