106	// 仍保持已拒绝终态，全部计时与决定信息原样保留，不追加过期记录、不产生
107	// 资金变动。三条拒绝路径（出资账户主动拒绝、会话吊销、策略停用）一致。
108	func TestRestoreRejectedRequestTimingAccepted(t *testing.T) {
109		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
110	
111		for _, cause := range []string{"payer", "revoke", "deactivate"} {
112			t.Run(cause+" rejection restores long after windows end", func(t *testing.T) {
113				data := buildRejectedTimingBackup(t, t0, cause, nil)
114				w2, err := restoreAt(data, t0.Add(48*time.Hour))
115				if err != nil {
116					t.Fatalf("legal rejection must restore: %v", err)
117				}
118				r, err := w2.Request("u1", "big")
119				if err != nil {
120					t.Fatal(err)
121				}
122				if r.State != RequestRejected {
123					t.Fatalf("state = %v, want rejected", r.State)
124				}
125				if !r.CreatedAt.Equal(t0) || !r.WaitDeadline.Equal(t0.Add(time.Hour)) ||
126					!r.DecidedAt.Equal(t0.Add(30*time.Minute)) {
127					t.Fatalf("timing rewritten: created %v deadline %v decided %v",
128						r.CreatedAt, r.WaitDeadline, r.DecidedAt)
129				}
130				wantApprover := "payer"
131				if cause == "revoke" {
132					wantApprover = ""
133				}
134				if r.ApproverAccountID != wantApprover {
135					t.Fatalf("approver = %q, want %q", r.ApproverAccountID, wantApprover)
136				}
137				if r.RejectReason == "" {
138					t.Fatal("reject reason lost")
139				}
140				// 终态不改写：不追加过期记录，余额不变。
141				if got := len(w2.Ledger()); got != 0 {
142					t.Fatalf("restore appended %d ledger entries", got)
143				}
144				if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
145					t.Fatalf("payer balance = %+v, want untouched", bal)
146				}
147			})
148		}
149	
150		t.Run("rejected exactly at created_at restores", func(t *testing.T) {
151			data := buildRejectedTimingBackup(t, t0, "payer", func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
152				r.DecidedAt = timeJSON(t0)
153			})
154			if _, err := restoreAt(data, t0.Add(time.Minute)); err != nil {
155				t.Fatalf("rejection exactly at created_at must be legal: %v", err)
156			}
157		})
158	
159		t.Run("rejection one nanosecond before deadline restores", func(t *testing.T) {
160			data := buildRejectedTimingBackup(t, t0, "payer", func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
161				r.DecidedAt = timeJSON(t0.Add(time.Hour - time.Nanosecond))
162			})
163			if _, err := restoreAt(data, t0.Add(time.Minute)); err != nil {
164				t.Fatalf("rejection 1ns before deadline must be legal: %v", err)
165			}
166		})
167	
168		t.Run("deadline bounded by policy end", func(t *testing.T) {
169			data := buildRejectedTimingBackup(t, t0, "payer", func(r *requestBackupV1, p *policyBackupV1, _ *sessionBackupV1) {
170				p.EndsAt = timeJSON(t0.Add(30 * time.Minute))
171				r.WaitDeadline = timeJSON(t0.Add(30 * time.Minute))
172				r.DecidedAt = timeJSON(t0.Add(15 * time.Minute))
173			})
174			if _, err := restoreAt(data, t0.Add(time.Minute)); err != nil {
175				t.Fatalf("policy-end bounded deadline: %v", err)
176			}
177		})
178	
179		t.Run("deadline bounded by session expiry", func(t *testing.T) {
180			data := buildRejectedTimingBackup(t, t0, "revoke", func(r *requestBackupV1, _ *policyBackupV1, s *sessionBackupV1) {
181				s.ExpiresAt = timeJSON(t0.Add(20 * time.Minute))
182				r.WaitDeadline = timeJSON(t0.Add(20 * time.Minute))
183				r.DecidedAt = timeJSON(t0.Add(10 * time.Minute))
184			})
185			if _, err := restoreAt(data, t0.Add(time.Minute)); err != nil {
186				t.Fatalf("session-expiry bounded deadline: %v", err)
187			}
188		})
189	
190		t.Run("timezone representation does not change outcome", func(t *testing.T) {
191			// 同一时刻的不同时区写法：t0+30m UTC 即 t0+31m30s +02:00 之前的瞬间。
192			data := buildRejectedTimingBackup(t, t0, "payer", func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
193				r.DecidedAt = timeJSON(t0.Add(30 * time.Minute).In(time.FixedZone("UTC+2", 2*3600)))
194			})
195			if _, err := restoreAt(data, t0.Add(time.Minute)); err != nil {
196				t.Fatalf("same instant in another zone must restore: %v", err)
197			}
198		})
199	}
200	
201	// TestRestoreRejectsRejectedTiming 验证已拒绝请求：等待截止缺失、被改长/改短，
202	// 或拒绝决定发生在提交前、截止时刻或之后，都必须让整个备份被拒绝——三条
203	// 拒绝路径统一适用，余额与累计金额自洽也不能放行。
204	func TestRestoreRejectsRejectedTiming(t *testing.T) {
205		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
206	
207		cases := []struct {
208			name   string
209			mutate func(*requestBackupV1, *policyBackupV1, *sessionBackupV1)
210			reason string
211		}{
212			{
213				name: "missing wait deadline",
214				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
215					r.WaitDeadline = timeJSON(time.Time{})
216				},
217				reason: "missing wait deadline",
218			},
219			{
220				name: "lengthened wait deadline",
221				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
222					r.WaitDeadline = timeJSON(t0.Add(2 * time.Hour))
223				},
224				reason: "does not match min",
225			},
226			{
227				name: "shortened wait deadline",
228				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
229					r.WaitDeadline = timeJSON(t0.Add(15 * time.Minute))
230				},
231				reason: "wait deadline",
232			},
233			{
234				name: "deadline claims session expiry but stored later",
235				mutate: func(r *requestBackupV1, _ *policyBackupV1, s *sessionBackupV1) {
236					s.ExpiresAt = timeJSON(t0.Add(20 * time.Minute))
237					// 正确截止应为 t0+20m，备份仍保存 t0+1h。
238				},
239				reason: "does not match min",
240			},
241			{
242				name: "rejection before created_at",
243				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
244					r.DecidedAt = timeJSON(t0.Add(-time.Nanosecond))
245				},
246				reason: "before created_at",
247			},
248			{
249				name: "rejection exactly at deadline",
250				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
251					r.DecidedAt = timeJSON(t0.Add(time.Hour))
252				},
253				reason: "strictly before wait deadline",
254			},
255			{
256				name: "rejection after deadline",
257				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
258					r.DecidedAt = timeJSON(t0.Add(time.Hour + time.Nanosecond))
259				},
260				reason: "strictly before wait deadline",
261			},
262		}
263		for _, cause := range []string{"payer", "revoke", "deactivate"} {
264			for _, tc := range cases {
265				t.Run(cause+"/"+tc.name, func(t *testing.T) {
266					data := buildRejectedTimingBackup(t, t0, cause, tc.mutate)
267					// 恢复时刻远近都不影响结论：只按备份记载的时间判断。
268					for _, at := range []time.Time{t0.Add(time.Minute), t0.Add(48 * time.Hour)} {
269						msg := assertRejectionTimingRejected(t, data, at)
270						if !strings.Contains(msg, tc.reason) {
271							t.Fatalf("error %q must explain %q", msg, tc.reason)
272						}
273					}
274				})
275			}
276		}
277	}
278	
279	// TestRestoreRejectedTimingConsistentBalancesCannotPass 验证余额与策略累计
280	// 金额完全自洽的备份，只要拒绝时间矛盾仍必须整体拒绝。
281	func TestRestoreRejectedTimingConsistentBalancesCannotPass(t *testing.T) {
282		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
283		data := buildRejectedTimingBackup(t, t0, "payer", func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
284			// 截止当时才拒绝：正常流程中该时刻请求已进入过期终态。
285			r.DecidedAt = timeJSON(t0.Add(time.Hour))
286		})
287		assertRejectionTimingRejected(t, data, t0.Add(time.Minute))
288	}
289	
290	// TestRestoreStandaloneRejectionLedgerEntriesKept 验证未被受理申请留下的独立
291	// 拒绝账本记录（没有对应请求或会话）不受拒绝时限核对影响，仍按原有规则保留。
292	func TestRestoreStandaloneRejectionLedgerEntriesKept(t *testing.T) {
293		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
294		data := buildRejectedTimingBackup(t, t0, "payer", nil)
295		var b backupV1
296		if err := json.Unmarshal(data, &b); err != nil {
297			t.Fatal(err)
298		}
299		// 追加两条没有对应请求的拒绝留痕：一条指向未知账户/请求，一条指向未知
300		// 会话时代的申请；时间任意，不参与请求时限核对。
301		b.Ledger = append(b.Ledger,
302			ledgerEntryBackupV1{
303				Kind: int(LedgerRejection), AccountID: "ghost", RequestID: "no-such-request",
304				Reason: "wallet: account not found: ghost", At: timeJSON(t0.Add(-time.Hour)),
305			},
306			ledgerEntryBackupV1{
307				Kind: int(LedgerRejection), AccountID: "u1", RequestID: "unknown",
308				Reason: "wallet: session not found: s9", At: timeJSON(t0.Add(90 * time.Minute)),
309			},
310		)
311		fixed, err := json.Marshal(&b)
312		if err != nil {
313			t.Fatal(err)
314		}
315		w2, err := restoreAt(fixed, t0.Add(48*time.Hour))
316		if err != nil {
317			t.Fatalf("standalone rejection ledger entries must restore: %v", err)
318		}
319		entries := w2.Ledger()
320		if len(entries) != 2 {
321			t.Fatalf("ledger len = %d, want 2", len(entries))
322		}
323		for i, e := range entries {
324			if e.Kind != LedgerRejection {
325				t.Fatalf("entry %d kind = %v, want rejection", i, e.Kind)
326			}
327		}
328		if entries[0].AccountID != "ghost" || entries[1].RequestID != "unknown" {
329			t.Fatalf("standalone rejection entries not preserved: %+v", entries)
330		}
331	}
